{
  "findings": [
    {
      "check_id": "CKV_AWS_17",
      "title": "Ensure all data stored in RDS is not publicly accessible",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance is potentially publicly accessible due to the 'publicly_accessible' attribute being set to a variable value that could be true."
    },
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have Multi-AZ enabled, which could lead to availability issues in case of a failure in one Availability Zone."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = false\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = true\n}",
  "fix_summary": "Set 'publicly_accessible' to false to prevent public access to the RDS instance and set 'multi_az' to true to enable Multi-AZ deployment for high availability."
}
